import{z as o,x as A,o as E,c as p,q as l,j as n,D as a,d as t,s,S as B,b as r}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"WebGPU 推理","description":"","frontmatter":{"title":"WebGPU 推理","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/webgpu-inference.md","filePath":"llm/webgpu-inference.md","lastUpdated":1791413859000}'),d={name:"llm/webgpu-inference.md"};function b(m,e,D,P,W,C){const i=A("Mermaid");return E(),p("div",null,[e[2]||(e[2]=l('<h1 id="webgpu-推理" tabindex="-1">WebGPU 推理 <a class="header-anchor" href="#webgpu-推理" aria-label="Permalink to &quot;WebGPU 推理&quot;">​</a></h1><div class="epigraph"><p>浏览器里的 GPU 没有 CUDA 运行时：计算着色器加上严格的内存配额，能跑的是量化后的小模型，不是把 vLLM 搬进标签页。</p><footer>—— W3C WebGPU；浏览器 LLM 见 MLC WebLLM 与 transformers.js 一类 TVM / ONNX Runtime Web 路径</footer></div><p><a href="/llm/mlx-apple">上一课</a>还有原生进程与统一内存。WebGPU 把计算放进沙箱：着色器、缓冲配额、无自定义特权内核。MLC 的 WebLLM 用 TVM 把模型编译到 WebGPU；transformers.js 常用 ONNX Runtime Web 或 WASM。本课写约束：权重要下载到浏览器、KV 占 JS/GPU 缓冲、decode 在带宽与启动开销双重劣势下跑。隐私（权重与数据不出页）是产品动机，不是性能动机。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>下载 4-bit 7B 仍是数 GB，首次 TTFT 含网络。配额与移动浏览器会直接拒绝。逐步：没有 <a href="/llm/flashattention">FlashAttention</a> 那种 CUDA 核，注意力是着色器或退化实现，\\(n\\) 稍长即炸。缺口是承认 Web 路径的模型级（1B–8B 量化、短上下文），以及预填充与 decode 的着色器启动开销。采样在 JS 或 WASM，词表扫描相对 GPU 着色器可能更刺眼——先修采样器内核的反面。</p><p><span class="marginnote">TTFT（Time To First Token）指从发出请求到看见第一个字的等待时间。数字感受一下：7B 参数做 4-bit 量化，每参数约 0.5 字节，仅权重就约 3.5 GB——相当于先下完一部标清电影，模型才说得出第一个字。所以浏览器产品必须把「加载中」当成一等交互来设计。</span></p><p>没有连续批：一页一个用户，\\(B=1\\)，工作点永远在带宽区。优化是量化、减层、短上下文，不是堆并发。</p><p><span class="marginnote">WebGPU 与 WebGL 不同。旧的 WebGL 路径不适合通用计算。检测能力失败时应回退 WASM CPU，并明确更慢。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>编译：TVM / ORT 把图降到 WGSL。分发：分片下载、缓存到 Origin Private File System。KV：固定最大 \\(n\\) 预留，碎片回到 OpenVINO NPU 那类问题。流式：id 在 Worker 里 generate，主线程 detokenize，注意 UTF-8 稳定前缀。投机在浏览器上草稿也得是小模型或早退，下一课端侧投机再写；Web 上内存更紧。</p><p><span class="marginnote">「着色器」原是显卡里给每个像素上色的小程序，WebGPU 把它推广成通用并行小程序：把一万条数据切一万份，每份由一个着色器实例同时处理。浏览器里的矩阵乘法全靠它跑，这也是为什么没有定制 CUDA 核时，注意力只能写成退化实现。</span></p><p><span class="marginnote">Origin Private File System（OPFS）可类比为浏览器分给每个网站的秘密仓库：用户在文件管理器里看不到里面的内容，但页面读写自己的权重分片不用征询下载文件夹。模型缓存在这里，第二次打开页面就不必重新下载数 GB。</span></p>',12)),(E(),n(B,null,{default:a(()=>[s(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20DL%5B%22%E5%88%86%E7%89%87%E4%B8%8B%E8%BD%BD%E6%9D%83%E9%87%8D%22%5D%20--%3E%20COMP%5B%22TVM%2FORT%20%E2%86%92%20WebGPU%22%5D%0A%20%20COMP%20--%3E%20STEP%5B%22%E7%9D%80%E8%89%B2%E5%99%A8%E4%B8%80%E6%AD%A5%20decode%22%5D%0A%20%20STEP%20--%3E%20JS%5B%22JS%2FWASM%20%E9%87%87%E6%A0%B7%22%5D%0A%20%20JS%20--%3E%20UI%5B%22%E7%A8%B3%E5%AE%9A%E5%89%8D%E7%BC%80%E4%B8%8A%E5%B1%8F%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=r("h2",{id:"机制",tabindex:"-1"},[t("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=r("p",null,"沙箱禁止持久内核与无限显存。每步着色器启动相对 CUDA Graph 更贵，小核更多伤。会计公式仍用，\\(B_{\\mathrm{HBM}}\\) 换成共享显存或系统内存。安全：模型文件来自源站，仍要完整性校验，避免恶意着色器或权重。这与 safetensors 的供应链同一类，只是运行在浏览器官辖。",-1)),(E(),n(B,null,{default:a(()=>[s(i,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E4%B8%80%E6%9D%A1%E7%94%9F%E6%88%90%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20B%7B%22%E8%83%BD%E5%87%91%E6%89%B9%E5%90%97%3F%22%7D%0A%20%20B%20--%3E%7C%22%E4%B8%80%E9%A1%B5%E4%B8%80%E7%94%A8%E6%88%B7%2C%20B%3D1%22%7C%20BW%5B%22%E6%AF%8F%E6%AD%A5%E9%83%BD%E8%A6%81%E9%87%8D%E8%AF%BB%E5%85%A8%E9%83%A8%E6%9D%83%E9%87%8D%20%E2%86%92%20%E5%8D%A1%E6%98%BE%E5%AD%98%E5%B8%A6%E5%AE%BD%22%5D%0A%20%20B%20--%3E%7C%22%E6%9C%8D%E5%8A%A1%E5%99%A8%E5%87%91%E5%A4%A7%E6%89%B9%22%7C%20COMP%5B%22%E5%A4%9A%E4%B8%AA%E8%AF%B7%E6%B1%82%E5%88%86%E6%91%8A%E4%B8%80%E6%AC%A1%E6%9D%83%E9%87%8D%E8%AF%BB%E5%8F%96%20%E2%86%92%20%E5%8D%A1%E7%AE%97%E5%8A%9B%22%5D%0A%20%20BW%20--%3E%20OPTW%5B%22%E4%BC%98%E5%8C%96%3A%20%E9%87%8F%E5%8C%96%20%2F%20%E5%87%8F%E5%B1%82%20%2F%20%E7%9F%AD%E4%B8%8A%E4%B8%8B%E6%96%87%22%5D%0A%20%20COMP%20--%3E%20OPTC%5B%22%E4%BC%98%E5%8C%96%3A%20%E8%BF%9E%E7%BB%AD%E6%89%B9%E5%A4%84%E7%90%86%E8%B0%83%E5%BA%A6%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[t(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=l('<p><span class="marginnote">常见误区：把服务器吞吐优化照搬到浏览器。服务器靠大批请求分摊权重读取，算的是算术强度；浏览器永远 B=1，每个字都要重新搬一遍几 GB 的权重，瓶颈只剩带宽。所以网页端该做的是把权重变小（量化、减层），而不是想办法凑批。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要承诺「在标签页跑 70B」。不要在 iOS Safari 的不稳定 WebGPU 上无检测直跑。下一课：真正的手机 NPU 部署，权限与工具链又不同。</p><p>出处：W3C WebGPU；MLC WebLLM；ORT Web。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>WebGPU 推理是沙箱着色器 + 下载配额；\\(B=1\\)、短上下文、强量化。</li><li>无 CUDA FA；长 \\(n\\) 先炸内存再谈算法。</li><li>首次延迟含下载；要用分片缓存。</li><li>采样与 detokenize 在 Worker；注意稳定前缀。</li><li>产品动机常是隐私与零安装，不是吞吐。</li><li>下一课：移动端 NPU。</li><li>出处：W3C WebGPU；MLC WebLLM。</li></ul>',6))])}const h=o(d,[["render",b]]);export{f as __pageData,h as default};
